// NewPlantingQuerySet starts a query over Planting rows on db.
func NewPlantingQuerySet(db *gorm.DB) PlantingQuerySet {
	return PlantingQuerySet{db: db.Model(&Planting{})}
}

// next copies the statement before changing it: gorm mutates a statement in place once it has been derived.
func (qs PlantingQuerySet) next() *gorm.DB { return qs.db.Session(&gorm.Session{}) }

func (qs PlantingQuerySet) col(name string) clause.Column {
	return clause.Column{Table: clause.CurrentTable, Name: name}
}

func (qs PlantingQuerySet) where(expr clause.Expression) PlantingQuerySet {
	return PlantingQuerySet{db: qs.next().Where(expr)}
}

func (qs PlantingQuerySet) fail(err error) PlantingQuerySet {
	db := qs.next()
	_ = db.AddError(err)
	return PlantingQuerySet{db: db}
}

func (qs PlantingQuerySet) order(name string, desc bool) PlantingQuerySet {
	return PlantingQuerySet{db: qs.next().Order(clause.OrderByColumn{Column: qs.col(name), Desc: desc})}
}

// GetDB returns the underlying query for what the query set does not cover (joins, preloads, locking).
func (qs PlantingQuerySet) GetDB() *gorm.DB { return qs.db }

// Select restricts the columns read.
